import requests
base='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/'
for term in ['breast complicated cyst ultrasound management','complicated cysts breast follow-up malignancy','breast cyst aspiration palpable mass management']:
 d=requests.get(base+'esearch.fcgi',params={'db':'pubmed','term':term,'retmode':'json','retmax':5},timeout=20).json()['esearchresult']
 print('\nQUERY',term,'COUNT',d['count'],'IDS',d['idlist'])
 if d['idlist']:
  x=requests.get(base+'esummary.fcgi',params={'db':'pubmed','id':','.join(d['idlist']),'retmode':'json'},timeout=20).json()['result']
  for i in d['idlist']:
   print(i,x[i].get('title',''))

import requests
base='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/'
ids=['15474446','11147439']
