 d=requests.get(base+'efetch.fcgi',params={'db':'pubmed','id':i,'retmode':'xml'},timeout=20).text
 print('\nPMID',i,'\n',d[:6000])
for url in ['https://www.uptodate.com/contents/breast-cysts','https://www.ncbi.nlm.nih.gov/books/NBK562196/']:
 try:
